function nidx(pts,p){let bi=0,bd=1e18;for(let i=0;i<pts.length;i++){const dx=(pts[i][0]-p[0])*111,dy=(pts[i][1]-p[1])*89,d=dx*dx+dy*dy;if(d<bd){bd=d;bi=i;}}return bi;}
TIMES.forEach(e=>{
  const pts=DAYROUTES[e[0]-1].pts,a=NAMEPOS[e[1]],b=NAMEPOS[e[2]];
  if(!a||!b)return;
  const m=pts[Math.round((nidx(pts,a)+nidx(pts,b))/2)];
  L.marker(m,{icon:L.divIcon({html:`<div class="tlbl mid">${e[3]}</div>`,className:'lmkwrap',iconSize:null,iconAnchor:[14,8]})}).addTo(gTime);
});
const pin=c=>`<svg width="26" height="36" viewBox="0 0 26 36"><path d="M13 1C6.4 1 1 6.4 1 13c0 8.8 12 22 12 22s12-13.2 12-22C25 6.4 19.6 1 13 1z" fill="${c}" stroke="#fff" stroke-width="2"/><circle cx="13" cy="13" r="5" fill="#fff"/></svg>`;
L.marker([36.249,137.636],{icon:L.divIcon({html:pin('#2f9e44'),className:'lmkwrap',iconSize:[26,36],iconAnchor:[13,35]}),zIndexOffset:1000})
